/**
 * Official brand marks in each platform's own brand color. LinkedIn isn't
 * distributed by simple-icons (trademark policy) — sourced from Font Awesome
 * Brands (CC BY 4.0) instead. All others sourced from simple-icons. Two
 * (IndexedDB, User, Browser) are generic UI glyphs, not brand marks — no
 * company logo exists for a browser API or a person/browser-window concept —
 * sourced from Heroicons (MIT), colored via `currentColor`.
 *
 * Icon data is exported as plain objects (`ICONS`) so non-React consumers —
 * e.g. `components/ui/Mermaid.tsx`, which injects icons into a mermaid.js
 * SVG via direct DOM manipulation — can build `<path>` elements from the
 * same verified path/color data the React components below render, with one
 * source of truth. `className` on the components should set a height (e.g.
 * "h-4") — width follows via `w-auto` to preserve each icon's aspect ratio.
 */

export type IconPath = { d: string; fillRule?: "evenodd"; clipRule?: "evenodd"; fill?: string };
export type IconData = { viewBox: string; color: string; paths: IconPath[] };

